import { useContext, createContext } from "react";
import { GoogleDocMessage, List } from "../common/types";
import { GoogleDocs, getRefListRange } from "../google";

export const PopupStates = ["login", "select-list", "no-access"] as const;
type PopupState = (typeof PopupStates)[number];

type DocsWidgetState = {
  document?: GoogleDocs.Document;
  selectedList?: List;
  hasReferenceList?: boolean;
  popupState?: PopupState;
};

type Action =
  | { type: "clearDocument" }
  | { type: "setSelctedList"; list: List }
  | { type: "setPopupState"; popupState: DocsWidgetState["popupState"] }
  | GoogleDocMessage;

const DocsWidgetPopupContext = createContext<DocsWidgetState | undefined>(undefined);

export const DocsWidgetPopupProvider = ({
  children,
  value,
}: {
  children: React.ReactNode;
  value: DocsWidgetState;
}) => {
  return <DocsWidgetPopupContext.Provider value={value}>{children}</DocsWidgetPopupContext.Provider>;
};

export const useDocsWidgetPopupContext = () => {
  const context = useContext(DocsWidgetPopupContext);
  if (context == null) {
    throw new Error("useDocsWidgetPopupContext must be used within a DocsWidgetPopupProvider");
  }
  return context;
};

export const docsWidgetReducer = (state: DocsWidgetState, action: Action): DocsWidgetState => {
  switch (action.type) {
    case "googleDoc": {
      const { document } = action;
      return {
        ...state,
        document,
        hasReferenceList: getRefListRange(document) !== undefined,
      };
    }
    case "clearDocument": {
      return {
        ...state,
        document: undefined,
        hasReferenceList: undefined,
      };
    }
    case "setSelctedList": {
      const { list } = action;
      return {
        ...state,
        selectedList: list,
      };
    }
    case "setPopupState": {
      const { popupState } = action;
      return {
        ...state,
        popupState,
      };
    }
    default:
      return state;
  }
};
