import { CUSTOM_ELEMENT_NAME, registerWebComponent } from "../docs-widget/docs-widget.webcomponent";

(async () => {
  if (document.getElementsByTagName(CUSTOM_ELEMENT_NAME).length > 0) {
    for (const existingBadge of document.getElementsByTagName(CUSTOM_ELEMENT_NAME)) {
      existingBadge?.parentNode?.removeChild(existingBadge);
    }
  }

  await registerWebComponent();
})();
