import * as TooltipPrimitive from "@radix-ui/react-tooltip";
import classNames from "classnames";
import { ComponentProps, ElementRef, forwardRef, useContext } from "react";
import { PortalContext } from "../PortalContext";

export const Provider = TooltipPrimitive.Provider;

export const Root = TooltipPrimitive.Root;

export const Trigger = TooltipPrimitive.Trigger;

export const Arrow = TooltipPrimitive.Arrow;

export const Content = forwardRef<
  ElementRef<typeof TooltipPrimitive.Content>,
  ComponentProps<typeof TooltipPrimitive.Content>
>(function Content({ children, className, sideOffset = 4, ...otherProps }, forwardedRef) {
  const { portalRef } = useContext(PortalContext);

  return (
    <TooltipPrimitive.Portal container={portalRef?.current}>
      <TooltipPrimitive.Content
        {...otherProps}
        ref={forwardedRef}
        role="tooltip"
        sideOffset={sideOffset}
        className={classNames(
          "max-w-xs origin-[var(--radix-tooltip-content-transform-origin)] text-balance rounded bg-navy-blue-12 px-2 py-1.5 text-center text-xs text-white shadow-lg",
          className,
        )}
      >
        {children}
      </TooltipPrimitive.Content>
    </TooltipPrimitive.Portal>
  );
});
