import { getCitationStyleOptions } from "@cgs/citation-engine/common";
import { List } from "@cgs/types";
import { GoogleDocs } from ".";
import { DOMParser } from "linkedom";
import { GoogleForbiddenError, GoogleUnauthorizedError } from "../common/errors";
import { DOCS_IFRAME, DOCS_SCROLL_AREA } from "./docs-selectors";

const baseUrl = "https://docs.googleapis.com/v1/documents/";
const USER_AGENT = "cgs-extension (gzip)";
const LOADING_LIST_PLACEHOLDER = "⟫⟫ Loading reference list…";
export const NAMED_RANGE_PREFIX = "cgs-ref-list-";
export const ZERO_WIDTH_MARKER = "\u200b\u200c\u200c\u200d\u200d\u200b\u200d";

export function getRefListNamedRange(document: GoogleDocs.Document): GoogleDocs.NamedRange | undefined {
  const namedRange = Object.values(document.namedRanges || {}).find((namedRange) =>
    namedRange.name.startsWith(NAMED_RANGE_PREFIX),
  );

  return namedRange;
}

export function getRefListRange(document: GoogleDocs.Document): GoogleDocs.Range | undefined {
  const firstRefListParagraphIndex = document.body.content.findIndex((content) =>
    content.paragraph?.elements[0]?.textRun?.content.startsWith(ZERO_WIDTH_MARKER),
  );

  if (firstRefListParagraphIndex === -1) {
    return undefined;
  }

  const startIndex = document.body.content[firstRefListParagraphIndex]?.startIndex;
  if (startIndex === undefined) {
    return undefined;
  }

  let endIndex: number | undefined;
  let currentParagraphIndex = firstRefListParagraphIndex;

  while (true) {
    const currentParagraph = document.body.content[currentParagraphIndex]?.paragraph;

    if (currentParagraph === undefined) {
      break;
    }

    const textRun = currentParagraph.elements[0]?.textRun?.content;
    if (textRun === "\n" && currentParagraph.elements.length === 1) {
      // new line between ref lst entries or at the end of the ref list
      endIndex = currentParagraph.elements[0]?.startIndex;
      currentParagraphIndex++;
      continue;
    }

    if (textRun === undefined || !textRun.startsWith(ZERO_WIDTH_MARKER)) {
      // not a ref list paragraph
      break;
    }

    const lastParagraphElement = currentParagraph.elements[currentParagraph.elements.length - 1];
    if (lastParagraphElement === undefined) {
      break;
    }

    // if the last element is a line break or not a textRun, use the startIndex of the last element else use the endIndex
    endIndex =
      lastParagraphElement.textRun?.content === "\n" || lastParagraphElement.textRun === undefined
        ? lastParagraphElement.startIndex
        : lastParagraphElement.endIndex;

    currentParagraphIndex++;
  }

  if (endIndex === undefined) {
    return;
  }

  return {
    startIndex,
    endIndex,
  };
}

export function makeBatchRequests(document: GoogleDocs.Document, list: List): Array<GoogleDocs.Requests> {
  const requests: Array<GoogleDocs.Requests> = [];

  let startIndex = document.body.content[document.body.content.length - 1]?.startIndex;
  if (!startIndex) {
    throw new Error("Invalid document");
  }

  const refListRange = getRefListRange(document);

  if (refListRange !== undefined) {
    startIndex = refListRange.startIndex;

    requests.push({
      deleteContentRange: {
        range: refListRange,
      },
    });
  }

  const placeHolderParagraph = document.body.content.find((content) => {
    const text = content.paragraph?.elements[0]?.textRun?.content;
    return text?.startsWith(LOADING_LIST_PLACEHOLDER);
  });

  if (placeHolderParagraph !== undefined) {
    requests.push({
      deleteContentRange: {
        range: {
          startIndex: placeHolderParagraph.startIndex,
          endIndex: placeHolderParagraph.endIndex,
        },
      },
    });

    startIndex = placeHolderParagraph.startIndex;
  }

  if (list.bibliography.length > 0) {
    // text insertions should be done in reverse order
    const bib = list.bibliography.reverse();

    for (let i = 0; i <= bib.length - 1; i++) {
      const text = bib[i]?.text;

      if (text === undefined) {
        // TODO: maybe throw? this should never happen
        continue;
      }

      const textToInsert = `${ZERO_WIDTH_MARKER}${text.replaceAll(/<[^>]*>?/gm, "")}\n`;

      requests.push({
        insertText: {
          location: {
            index: startIndex,
          },
          text: textToInsert,
        },
      });

      const ranges = parseFormatRanges(text);
      for (const range of ranges) {
        requests.push({
          updateTextStyle: {
            range: {
              startIndex: startIndex + range.range.startIndex + ZERO_WIDTH_MARKER.length,
              endIndex: startIndex + range.range.endIndex + ZERO_WIDTH_MARKER.length,
            },
            textStyle: {
              bold: range.formats.bold || false,
              italic: range.formats.italic || false,
              baselineOffset: range.formats.sup ? "SUPERSCRIPT" : range.formats.sub ? "SUBSCRIPT" : "NONE",
            },
            fields: "bold,italic,baselineOffset",
          },
        });
      }

      const citationStyleOptions = getCitationStyleOptions(list.settings.citationStyle);
      const textIndent = Number(citationStyleOptions.bibliographyStyle.textIndent?.replace("pt", "")) * -1;
      requests.push({
        updateParagraphStyle: {
          range: {
            startIndex,
            endIndex: startIndex + textToInsert.length,
          },
          paragraphStyle: {
            indentStart: {
              magnitude: textIndent,
              unit: "PT",
            },
            lineSpacing: lineHeightToSpacing(citationStyleOptions.bibliographyStyle.lineHeight),
          },
          fields: "indentStart,lineSpacing",
        },
      });
    }
  }

  return requests;
}

function lineHeightToSpacing(lineHeight: string) {
  const lineHeightNumber = Number(lineHeight.replace("%", ""));
  return Number.isNaN(lineHeightNumber) ? undefined : lineHeightNumber;
}

export async function fetchDocument(
  documentId: string,
  accessToken: string,
  signal?: AbortSignal,
): Promise<GoogleDocs.Document> {
  const response = await fetch(`${baseUrl}${documentId}`, {
    signal,
    headers: {
      Authorization: `Bearer ${accessToken}`,
      "accept-encoding": "gzip",
      "user-agent": USER_AGENT,
    },
  });

  if (response.ok) {
    return response.json() as unknown as GoogleDocs.Document;
  } else {
    if (response.status === 401) {
      throw new GoogleUnauthorizedError();
    }

    if (response.status === 403) {
      throw new GoogleForbiddenError();
    }

    throw new Error("Error fetching document");
  }
}

export async function batchUpdateDocument(
  document: GoogleDocs.Document,
  accessToken: string,
  requests: Array<GoogleDocs.Requests>,
) {
  const response = await fetch(`${baseUrl}${document.documentId}:batchUpdate`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${accessToken}`,
      "accept-encoding": "gzip",
      "user-agent": USER_AGENT,
    },
    body: JSON.stringify({ requests, writeControl: { targetRevisionId: document.revisionId } }),
  });

  if (response.ok) {
    return response.json();
  } else {
    throw new Error("Error updating document");
  }
}

function getDocsIframeWindow() {
  const iframeElement = document.querySelector<HTMLIFrameElement>(DOCS_IFRAME);
  if (!iframeElement) {
    return;
  }

  return iframeElement.contentWindow;
}

export function getScrollAreaBoundingClientRect() {
  const scrollArea = document.querySelector(DOCS_SCROLL_AREA);

  if (!scrollArea) {
    return;
  }

  return scrollArea.getBoundingClientRect();
}

export function getSelectedText() {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const iframeWindow = getDocsIframeWindow() as any;
  if (!iframeWindow) {
    return;
  }

  const copyEvent = new iframeWindow.CustomEvent("copy", { bubbles: true });

  const contentEditable = iframeWindow.document.querySelector("[contenteditable=true]");
  if (!contentEditable) {
    return;
  }

  // Google Docs will put the current selected text into hidden iframe when a "copy" event is triggered
  contentEditable.dispatchEvent(copyEvent);

  return contentEditable.innerText;
}

export function pastePlaceholder() {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const iframeWindow = getDocsIframeWindow() as any;
  if (!iframeWindow) {
    return;
  }

  const pasteEvent = new iframeWindow.ClipboardEvent("paste", {
    clipboardData: new iframeWindow.DataTransfer(),
    bubbles: true,
  });

  pasteEvent.clipboardData.setData("text/plain", `\n${LOADING_LIST_PLACEHOLDER}\n`);

  const contentEditable = iframeWindow.document.querySelector("[contenteditable=true]");
  if (!contentEditable) {
    return;
  }

  contentEditable.dispatchEvent(pasteEvent);
}

type ParsedText = {
  content: string | null;
  formats: { bold?: boolean; italic?: boolean; sup?: boolean; sub?: boolean };
};

export const parseNodes = (childNodes: ChildNode[], formats: ParsedText["formats"]): ParsedText[] =>
  childNodes.reduce<ParsedText[]>((prev, node) => {
    if (node.nodeName === "#text") {
      return [...prev, { content: node.textContent, formats: { ...formats } }];
    } else {
      return [
        ...prev,
        ...parseNodes(Array.from(node.childNodes), {
          bold: node.nodeName === "B" ? true : formats.bold,
          italic: node.nodeName === "I" ? true : formats.italic,
          sup: node.nodeName === "SUP" ? true : formats.sup,
          sub: node.nodeName === "SUB" ? true : formats.sub,
        }),
      ];
    }
  }, []);

type ParsedRange = {
  range: GoogleDocs.Range;
  formats: ParsedText["formats"];
};

export function parseFormatRanges(text: string) {
  const parser = new DOMParser();
  const document = parser.parseFromString(text, "text/html");

  const parsedText = parseNodes(Array.from(document.childNodes), {});

  const positions = parsedText.reduce<Array<ParsedRange>>((prev, node) => {
    if (node.content === null) {
      return prev;
    }

    const startIndex = prev[prev.length - 1]?.range.endIndex || 0;
    const endIndex = startIndex + node.content.length;

    return [...prev, { range: { startIndex, endIndex }, formats: node.formats }];
  }, []);

  return positions;
}
