import { PortalContext } from "@cgs/ui";
import { DocsBadgePopup } from "./DocsWidgetPopup";
import { useEffect, useRef, useState } from "react";
import { SessionStorageProvider } from "../components/SessionStorageProvider";
import { SettingsProvider } from "../settings/SettingsContext";
import { TooltipProvider } from "@radix-ui/react-tooltip";
import { I18nextProvider } from "react-i18next";
import i18n from "../common/i18n";
import { sendMessage } from "../common/messaging";
import { Variant } from "@cgs/analytics";

export const DocsBadgeContainer = () => {
  const ref = useRef<HTMLDivElement | null>(null);
  const [variant, setVariant] = useState<Variant | undefined>();

  useEffect(() => {
    (async () => {
      const variantResponse = await sendMessage({
        type: "fetchAmplitudeVariant",
        key: "cg-browser-extension-docs-widget",
      });

      if (variantResponse?.type === "amplitudeVariant") {
        setVariant(variantResponse.variant);
      }
    })();
  }, []);

  if (variant?.value !== "on") {
    return null;
  }

  return (
    <I18nextProvider i18n={i18n}>
      <PortalContext.Provider value={{ portalRef: ref }}>
        <TooltipProvider>
          <SessionStorageProvider>
            <SettingsProvider>
              <div className="font-serif text-base leading-5 text-navy-blue-12 antialiased" ref={ref}>
                <DocsBadgePopup />
              </div>
            </SettingsProvider>
          </SessionStorageProvider>
        </TooltipProvider>
      </PortalContext.Provider>
    </I18nextProvider>
  );
};
