import { forwardRef, useEffect, useState } from "react";
import { LogoIcon } from "../components/Logo";
import { Tooltip } from "@cgs/ui";
import { useTranslation } from "react-i18next";

export type DocsWidgetButtonProps = {
  open: boolean;
  className?: string;
};

export const DocsWidgetButton = forwardRef<HTMLButtonElement, DocsWidgetButtonProps>(function Button(
  { open, ...props },
  ref,
) {
  const [disabled, setDisabled] = useState<boolean>(false);
  const { t } = useTranslation();

  useEffect(() => {
    if (open) {
      setDisabled(true);
    } else {
      // makes controlled popover work
      setTimeout(() => {
        setDisabled(false);
      }, 200);
    }
  }, [open]);

  return (
    <Tooltip.Root delayDuration={200}>
      <Tooltip.Trigger asChild>
        <div className="z-[751] flex items-center gap-x-2">
          <button
            {...props}
            disabled={disabled}
            className="-mt-[1px] flex h-[30px] w-[30px] items-center justify-center rounded hover:bg-[#dfe5ed]"
            ref={ref}
            aria-label={t("docsWidget.button.tooltip")}
          >
            <LogoIcon className="h-4 fill-orange-9" />
          </button>
        </div>
      </Tooltip.Trigger>
      <Tooltip.Content align="center" side="bottom" sideOffset={8} className="text-xs text-navy-blue-11">
        {t("docsWidget.button.tooltip")}
      </Tooltip.Content>
    </Tooltip.Root>
  );
});
