import {
  CitationStyle,
  UnverifiedCitationStyle,
  UnverifiedCitationStyles,
  PromotedCitationStyle,
  PromotedCitationStyles,
} from "../types";

export function isPromotedCitationStyle(value: unknown): value is PromotedCitationStyle {
  if (!Array.isArray(value)) {
    return false;
  }
  if (value.length != 2) {
    return false;
  }

  const [id, variation] = value || [null, null];

  return PromotedCitationStyles.find((style) => style[0] === id && style[1] === variation) != null;
}

export function isPromotedCitationStyleId(value: unknown): value is PromotedCitationStyle[0] {
  return PromotedCitationStyles.some((style) => style[0] === value);
}

export function isUnverifiedCitationStyle(value: unknown): value is UnverifiedCitationStyle {
  if (!Array.isArray(value)) {
    return false;
  }
  if (value.length != 2) {
    return false;
  }

  const [id, variation] = value || [null, null];

  return UnverifiedCitationStyles.find((style) => style[0] === id && style[1] === variation) != null;
}

export function isCitationStyle(value: unknown): value is CitationStyle {
  return isPromotedCitationStyle(value) || isUnverifiedCitationStyle(value);
}

export { getCitationStyleOptions } from "./options";
export { getSourceTitleTextCase } from "./text-casing";
