import { Dispatch, SetStateAction, useCallback, useState, useEffect } from "react";

type AssertFunction<T> = (data: unknown) => asserts data is T;

export function useLocalStorage<T>(key: string, assert: AssertFunction<T>, defaultValue: T) {
  const [storedValue, setStoredValue] = useState(defaultValue);

  useEffect(() => {
    try {
      (async () => {
        const result = await chrome.storage.local.get(key);
        const parsed = JSON.parse(result[key] ?? "null");
        assert(parsed);
        setStoredValue(parsed);
      })();
    } catch {
      chrome.storage.local.remove(key);
    }
  }, [assert, key]);

  const setValue: Dispatch<SetStateAction<T>> = useCallback(
    async (value) => {
      const newValue = value instanceof Function ? value(storedValue) : value;
      setStoredValue(newValue);
      await chrome.storage.local.set({ [key]: JSON.stringify(newValue) });
    },
    [key, storedValue],
  );

  return [storedValue, setValue] as const;
}
