import { UserInfo } from "@cgs/types";
import { Folder } from "../../common/types";
import { createContext, useContext, useEffect, useState } from "react";

type StorageContextProps = {
  userInfo: UserInfo | undefined;
  folders: Array<Folder> | undefined;
};

const StorageContext = createContext<StorageContextProps | undefined>(undefined);

export function useSessionStorageContext() {
  const context = useContext(StorageContext);
  if (context == null) {
    throw new Error("useSessionStorageContext must be used within a StorageContext.Provider");
  }
  return context;
}

export const SessionStorageProvider = ({ children }: { children: React.ReactNode }) => {
  const [userInfo, setUserInfo] = useState<UserInfo | undefined>(undefined);
  const [folders, setFolders] = useState<Array<Folder> | undefined>(undefined);

  useEffect(() => {
    chrome.storage.session.get(["userInfo", "folders"], ({ userInfo: storedUserInfo, folders: storedFolders }) => {
      setUserInfo(storedUserInfo);
      setFolders(storedFolders);
    });
    const storageOnChanged = (changes: { [key: string]: chrome.storage.StorageChange }) => {
      const newUserInfo = changes.userInfo?.newValue;
      if (newUserInfo) {
        setUserInfo(newUserInfo);
      }
      const newFolders = changes.folders?.newValue;
      if (newFolders) {
        setFolders(newFolders);
      }
    };
    chrome.storage.onChanged.addListener(storageOnChanged);
    return () => chrome.storage.onChanged.removeListener(storageOnChanged);
  }, []);

  return <StorageContext.Provider value={{ userInfo, folders }}>{children}</StorageContext.Provider>;
};
