import "@webcomponents/custom-elements";
import { BaseWebComponent } from "@cgs/ui";
import { DocsBadgeContainer } from "./DocsWidgetContainer";
import { injectDocsSlidingDialog } from "./notifications";
import {
  DOCS_SIDE_TOOLBAR,
  DOCS_TOOLBAR_BUTTON_CLASS,
  DOCS_TOOLBAR_SEPARATOR_CLASS,
  SCRIBBR_DOCS_MENUBAR_BUTTON,
  SCRIBBR_DOCS_NOTIFICATION_DIALOG,
} from "../google/docs-selectors";

export const CUSTOM_ELEMENT_NAME = `scribbr-docs-badge${process.env.NODE_ENV === "development" ? "-dev" : ""}`;

export class DocsBadgeWebComponent extends BaseWebComponent {
  parseAttributes(attributes: Record<string, unknown>) {
    return attributes;
  }

  async createStyleSheet() {
    const url = chrome.runtime.getURL("gdocs.css");
    const css = await fetch(url).then((resp) => resp.text());
    const styleSheet = new CSSStyleSheet();
    return styleSheet.replace(css);
  }

  createReactNode() {
    return <DocsBadgeContainer />;
  }
}

export async function registerWebComponent() {
  const { settings } = await chrome.storage.local.get("settings");
  if (settings && settings.disableGoogleDocsIntegration) {
    return;
  }

  if (!customElements.get(CUSTOM_ELEMENT_NAME)) {
    customElements.define(CUSTOM_ELEMENT_NAME, DocsBadgeWebComponent);
  }

  const slidingdialog = document.querySelector(SCRIBBR_DOCS_NOTIFICATION_DIALOG);
  if (!slidingdialog) {
    injectDocsSlidingDialog();
  }

  const separator = document.createElement("div");
  separator.className = DOCS_TOOLBAR_SEPARATOR_CLASS;
  separator.setAttribute("role", "separator");
  separator.setAttribute("aria-disabled", "true");
  separator.setAttribute("aria-hidden", "false");
  separator.style.userSelect = "none";

  const toolbarButton = document.createElement("div");
  toolbarButton.id = SCRIBBR_DOCS_MENUBAR_BUTTON;
  toolbarButton.className = DOCS_TOOLBAR_BUTTON_CLASS;
  toolbarButton.setAttribute("role", "button");
  toolbarButton.setAttribute("aria-disabled", "false");
  toolbarButton.setAttribute("aria-hidden", "false");
  toolbarButton.style.userSelect = "none";

  const element = document.createElement(CUSTOM_ELEMENT_NAME);
  toolbarButton.appendChild(element);

  const docsSideToolbar = document.querySelector(DOCS_SIDE_TOOLBAR);

  if (docsSideToolbar) {
    docsSideToolbar.prepend(toolbarButton);
  }
}
