export function showNotification(message: string) {
  const dialogTextElement = document.querySelector("#scribbr-docs-suggestiondialog-title-text") as HTMLElement;
  const slidingdialog = document.querySelector("#scribbr-docs-slidingdialog-id") as HTMLElement;
  if (dialogTextElement && slidingdialog) {
    dialogTextElement.innerText = message;
    slidingdialog.style.height = "auto";
    slidingdialog.style.opacity = "1";
    slidingdialog.style.marginTop = "0px";
    setTimeout(() => {
      hideNotification();
    }, 3000);
  }
}

export function hideNotification() {
  const slidingdialog = document.querySelector("#scribbr-docs-slidingdialog-id") as HTMLElement;
  if (slidingdialog) {
    slidingdialog.style.marginTop = "-40px";
    setTimeout(() => {
      slidingdialog.style.opacity = "0";
      slidingdialog.style.height = "0";
    }, 200);
  }
}

export function injectDocsSlidingDialog() {
  const docsSuggestionDialog = document.querySelector("#docs-suggestiondialog-id");

  if (docsSuggestionDialog) {
    const docsSlidingDialogWrapper = document.createElement("div");
    docsSlidingDialogWrapper.className = "docs-slidingdialog-wrapper";
    docsSlidingDialogWrapper.setAttribute("aria-labelledby", "docs-suggestiondialog-list-updated");

    const docsSlidingDialogHolder = document.createElement("div");
    docsSlidingDialogHolder.className = "docs-slidingdialog-holder";
    docsSlidingDialogWrapper.appendChild(docsSlidingDialogHolder);

    const docsSlidingDialog = document.createElement("div");
    docsSlidingDialog.id = "scribbr-docs-slidingdialog-id";
    docsSlidingDialog.className = "docs-slidingdialog";
    docsSlidingDialog.setAttribute("role", "dialog");
    docsSlidingDialog.setAttribute("tabindex", "0");
    docsSlidingDialog.style.transition = "margin .2s linear";
    docsSlidingDialog.style.opacity = "0";
    docsSlidingDialog.style.height = "0";
    docsSlidingDialog.style.marginTop = "-40px";
    docsSlidingDialogHolder.appendChild(docsSlidingDialog);

    const docsSlidingDialogContent = document.createElement("div");
    docsSlidingDialogContent.id = "docs-slidingdialog-content";
    docsSlidingDialogContent.className = "docs-slidingdialog-content goog-inline-block";
    docsSlidingDialogContent.setAttribute("aria-label", "Reference list updated");
    docsSlidingDialog.appendChild(docsSlidingDialogContent);

    const docsSuggestionDialogContent = document.createElement("div");
    docsSuggestionDialogContent.className = "docs-suggestiondialog-content docs-material";
    docsSlidingDialogContent.appendChild(docsSuggestionDialogContent);

    const docsSuggestionDialogListUpdated = document.createElement("div");
    docsSuggestionDialogListUpdated.id = "docs-suggestiondialog-list-updated";
    docsSuggestionDialogListUpdated.setAttribute("tabindex", "-1");
    docsSuggestionDialogContent.appendChild(docsSuggestionDialogListUpdated);

    const docsSuggestionDialogTitleText = document.createElement("div");
    docsSuggestionDialogTitleText.id = "scribbr-docs-suggestiondialog-title-text";
    docsSuggestionDialogTitleText.className = "docs-suggestiondialog-title-text goog-inline-block";
    docsSuggestionDialogListUpdated.appendChild(docsSuggestionDialogTitleText);

    const docsSlidingDialogCloseContainer = document.createElement("div");
    docsSlidingDialogCloseContainer.className =
      "docs-slidingdialog-close-container goog-inline-block docs-material";
    docsSlidingDialog.appendChild(docsSlidingDialogCloseContainer);

    const docsSlidingDialogButtonClose = document.createElement("div");
    docsSlidingDialogButtonClose.className = "docs-slidingdialog-button-close goog-flat-button goog-inline-block";
    docsSlidingDialogButtonClose.setAttribute("aria-label", "Close");
    docsSlidingDialogButtonClose.setAttribute("role", "button");
    docsSlidingDialogButtonClose.setAttribute("aria-disabled", "false");
    docsSlidingDialogButtonClose.setAttribute("tabindex", "0");
    docsSlidingDialogButtonClose.setAttribute("style", "user-select: none;");
    docsSlidingDialogCloseContainer.appendChild(docsSlidingDialogButtonClose);

    const docsSlidingDialogOuterBox = document.createElement("div");
    docsSlidingDialogOuterBox.className = "goog-flat-button-outer-box goog-inline-block";
    docsSlidingDialogButtonClose.appendChild(docsSlidingDialogOuterBox);

    const docsSlidingDialogInnerBox = document.createElement("div");
    docsSlidingDialogInnerBox.className = "goog-flat-button-inner-box goog-inline-block";
    docsSlidingDialogOuterBox.appendChild(docsSlidingDialogInnerBox);

    const docsIcon = document.createElement("div");
    docsIcon.className = "docs-icon goog-inline-block";
    docsIcon.onclick = hideNotification;
    docsSlidingDialogInnerBox.appendChild(docsIcon);

    const docsIconImgContainer = document.createElement("div");
    docsIconImgContainer.className = "docs-icon-img-container docs-icon-img docs-icon-close";
    docsIconImgContainer.setAttribute("aria-hidden", "true");
    docsIconImgContainer.innerText = "&nbsp;";
    docsIcon.appendChild(docsIconImgContainer);

    docsSuggestionDialog.appendChild(docsSlidingDialogWrapper);
  }
}
