import { ReactNode } from "react";
import { Root, createRoot } from "react-dom/client";

export abstract class BaseWebComponent<
  Props extends Record<string, unknown> = Record<string, unknown>,
> extends HTMLElement {
  root: ShadowRoot;
  main: HTMLElement;
  reactRoot: Root;

  constructor() {
    super();
    this.injectFontFaceToDocument();
    this.root = this.attachShadow({ mode: "open" });
    this.main = document.createElement("main");
    this.reactRoot = createRoot(this.main);
  }

  /**
   * Parse the attributes passed to the component. This is useful for converting
   * string attributes to their proper types. For example, if you have a component
   * that takes a number, you can convert the string attribute to a number. n.b. This
   * is not a replacement for React's prop types, as we can only support primitive types.
   * It is suggested to parse these attributes through `zod`. For example:
   * ```ts
   * return z.object({
   *  locale: z.enum(Locales),
   *  createdDate: z.coerce.date(),
   *  count: z.coerce.number(),
   *  isDisabled: z.enum(["true", "false"])
   *    .optional()
   *    .transform((x) => (x ? x === "true" : undefined))
   * }).parse(attributes);
   * ```
   * @param attributes Attributes passed to the component
   */
  abstract parseAttributes(attributes: Record<string, unknown>): Props;

  /**
   * Create a stylesheet to be used by the component.
   * The stylesheet will be applied to the shadow root.
   * Two common use cases are to either fetch a CSS file, or import a CSS file.
   */
  abstract createStyleSheet(): Promise<CSSStyleSheet>;

  /**
   * Create the react component or application that will be rendered inside the component.
   */
  abstract createReactNode(props: Props): ReactNode;

  private getPropsFromAttributes(): Props {
    const attributes: Record<string, unknown> = {};
    for (let i = 0; i < this.attributes.length; i++) {
      const attr = this.attributes[i];
      if (attr) {
        attributes[attr.name] = attr.value;
      }
    }
    return this.parseAttributes(attributes);
  }

  async connectedCallback() {
    const styleSheet = await this.createStyleSheet();
    this.root.adoptedStyleSheets = [styleSheet];
    this.root.appendChild(this.main);
    const props = this.getPropsFromAttributes();
    const reactNode = this.createReactNode(props);
    this.reactRoot.render(reactNode);
  }

  disconnectedCallback() {
    this.reactRoot.unmount();
  }

  private injectFontFaceToDocument() {
    if (document.getElementById("scribbr-fonts")) {
      return;
    }

    const style = document.createElement("style");
    style.id = "scribbr-fonts";
    // web components do not support @font-face, so these need to be inject outisde of shadow dom
    style.innerHTML = `
    @font-face {
      font-family: "Inter";
      src: url(https://www.scribbr.com/wp-content/themes/scribbr-2017/dist/fonts/inter/Inter-Regular.woff2) format("woff2"), url(https://www.scribbr.com/wp-content/themes/scribbr-2017/dist/fonts/inter/Inter-Regular.woff) format("woff");
      font-style: normal;
      font-display: swap;
      font-weight: 400;
    }
    @font-face {
      font-family: "Inter";
      src: url(https://www.scribbr.com/wp-content/themes/scribbr-2017/dist/fonts/inter/Inter-SemiBold.woff2) format("woff2"), url(https://www.scribbr.com/wp-content/themes/scribbr-2017/dist/fonts/inter/Inter-SemiBold.woff) format("woff");
      font-style: normal;
      font-display: swap;
      font-weight: 600;
    }
    @font-face {
      font-family: "Inter";
      src: url(https://www.scribbr.com/wp-content/themes/scribbr-2017/dist/fonts/inter/Inter-Italic.woff2) format("woff2"), url(https://www.scribbr.com/wp-content/themes/scribbr-2017/dist/fonts/inter/Inter-Italic.woff) format("woff");
      font-style: italic;
      font-display: swap;
      font-weight: 400;
    }`;
    document.head.appendChild(style);
  }
}
