import * as Popover from "@radix-ui/react-popover";
import { DocsWidgetButton } from "./DocsWidgetButton";
import { useCallback, useContext, useEffect, useMemo, useReducer, useState } from "react";
import { Button, Icon, PortalContext, Select } from "@cgs/ui";
import { Logo } from "../components/Logo";
import { UserLevel } from "@cgs/types";
import { List } from "../common/types";
import { useSettingsContext } from "../settings/SettingsContext";
import { pastePlaceholder } from "../google/docs-utils";
import { DocsWidgetPopupProvider, docsWidgetReducer, useDocsWidgetPopupContext } from "./DocsWidgetState";
import { sendMessage } from "../common/messaging";
import { useSessionStorageContext } from "../components/SessionStorageProvider";
import { showNotification } from "./notifications";
import { useLocalStorage } from "../common/useLocalStorage";
import { useTranslation } from "react-i18next";
import { CircleCheck } from "@cgs/ui/components/Icon";
import classNames from "classnames";

export const DocsBadgePopup = () => {
  const [open, setOpen] = useState(false);
  const { settings, saveSettings } = useSettingsContext();
  const [state, dispatch] = useReducer(docsWidgetReducer, { hasReferenceList: false });
  const { selectedList, hasReferenceList } = state;
  const { userInfo, folders } = useSessionStorageContext();
  const { portalRef } = useContext(PortalContext);
  const [docsIntegrationSeen, setDocsIntegrationSeen] = useLocalStorage("docsIntegrationSeen", Boolean, true);
  const { t } = useTranslation();

  useEffect(() => {
    if (!docsIntegrationSeen) {
      setOpen(true);
      setDocsIntegrationSeen(true);
    }
  }, [docsIntegrationSeen, setDocsIntegrationSeen]);

  // fetch user info when the popup is opened
  useEffect(() => {
    if (open) {
      (async () => {
        await sendMessage({ type: "fetchUserInfo" });

        if (state.popupState !== undefined) {
          await sendMessage({
            type: "logEvent",
            event: {
              name: "Citation Generator Browser Extension Docs Widget Opened",
              data: {
                extension_language: "en-US",
                popup_state: state.popupState,
              },
            },
          });
        }
      })();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);

  // fetch google doc when the popup is opened and the user is logged in and has a token
  useEffect(() => {
    (async () => {
      if (open && settings.googleDocsToken != undefined && userInfo?.level === UserLevel.REGISTERED) {
        const docsId =
          window.location.hostname === "docs.google.com" ? window.location.pathname.split("/")[3] : undefined;
        if (docsId) {
          dispatch({ type: "clearDocument" });
          const googleDocResponse = await sendMessage({
            type: "fetchGoogleDoc",
            docsId,
            token: settings.googleDocsToken,
          });
          switch (googleDocResponse.type) {
            case "googleDoc": {
              dispatch(googleDocResponse);
              break;
            }
            case "error": {
              if (googleDocResponse.errorType === "GoogleUnauthorizedError") {
                saveSettings({ googleDocsToken: undefined });
              }
              if (googleDocResponse.errorType === "GoogleForbiddenError") {
                dispatch({ type: "setPopupState", popupState: "no-access" });
              }
              break;
            }
          }
        }
      }
    })();

    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, settings.googleDocsToken, userInfo?.level]);

  useEffect(() => {
    if (folders && folders.length > 0) {
      const lists = folders.flatMap((folder) => folder.lists);
      if (lists[0] === undefined) {
        return;
      }

      const list = lists.find((list) => list.id === selectedList?.id) || settings.selectedList || lists[0];

      dispatch({ type: "setSelctedList", list });
      saveSettings({ selectedList: list });
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [folders, selectedList, settings.selectedList]);

  useEffect(() => {
    if (userInfo?.level !== UserLevel.REGISTERED || settings.googleDocsToken === undefined) {
      return dispatch({ type: "setPopupState", popupState: "login" });
    }

    dispatch({ type: "setPopupState", popupState: "select-list" });
  }, [settings.googleDocsToken, userInfo?.level]);

  const handleListValueChange = async (value: string) => {
    const list = folders?.flatMap((folder) => folder.lists)?.find((list) => list.id === value);

    if (list) {
      dispatch({ type: "setSelctedList", list });
    }
  };

  if (state.popupState === undefined) {
    return null;
  }

  return (
    <DocsWidgetPopupProvider value={state}>
      <Popover.Root open={open}>
        <Popover.Trigger asChild onClick={() => setOpen(true)}>
          <DocsWidgetButton open={open} />
        </Popover.Trigger>
        <Popover.Portal container={portalRef?.current}>
          <Popover.Content
            align="end"
            side="bottom"
            className="mt-3 w-[348px] space-y-4 rounded bg-white shadow-[0_2px_6px_2px_rgba(60,64,67,.15)]"
            onOpenAutoFocus={(e) => {
              // https://github.com/radix-ui/primitives/issues/2248
              // prevents Tooltip from showing when opening the popover
              e.preventDefault();
            }}
            onCloseAutoFocus={(e) => {
              // same as above
              e.preventDefault();
            }}
            onPointerDownOutside={() => setOpen(false)}
          >
            <div className="flex h-full w-auto flex-col justify-start">
              <div className="flex h-[48px] w-full flex-row border-b border-navy-blue-6 px-4 py-3.5">
                <a href="https://www.scribbr.com/" target="_blank" rel="noreferrer" className="grow">
                  <Logo className="h-5" />
                </a>

                <a
                  href={chrome.runtime.getURL("settings.html")}
                  target="_blank"
                  rel="noreferrer"
                  aria-label={t("appFooter.settings")}
                  className="flex h-[20px] w-[20px] items-center justify-center"
                >
                  <Icon.Gear className="h-4 fill-navy-blue-11 hover:fill-navy-blue-12" />
                </a>
              </div>
              <div className="text-wrap p-5">
                {
                  {
                    login: <Login onClick={() => setOpen(false)} />,
                    "select-list": (
                      <SelectAndInsertList
                        onListValueChange={handleListValueChange}
                        onListInserted={(list) => {
                          setOpen(false);
                          showNotification(
                            hasReferenceList
                              ? t("docsWidget.notifications.listUpdated")
                              : t("docsWidget.notifications.listInserted"),
                          );
                          sendMessage({
                            type: "logEvent",
                            event: {
                              name: hasReferenceList
                                ? "Citation Generator Browser Extension Docs Widget list updated"
                                : "Citation Generator Browser Extension Docs Widget list inserted",
                              data: {
                                extension_language: "en-US",
                                citation_language: "en-US",
                                citation_style: list.settings.citationStyle[0],
                                citation_style_variation: list.settings.citationStyle[1],
                              },
                            },
                          });
                        }}
                        onOpenGenerator={() => {
                          setOpen(false);
                        }}
                        onError={() => {
                          setOpen(false);
                          showNotification(
                            hasReferenceList
                              ? t("docsWidget.notifications.updateFailed")
                              : t("docsWidget.notifications.insertFailed"),
                          );
                        }}
                      />
                    ),
                    "no-access": (
                      <div className="text-navy-blue text-center text-sm">{t("docsWidget.noAccess")}</div>
                    ),
                  }[state.popupState]
                }
              </div>
            </div>
          </Popover.Content>
        </Popover.Portal>
      </Popover.Root>
    </DocsWidgetPopupProvider>
  );
};

const SelectAndInsertList = ({
  onListValueChange,
  onListInserted,
  onOpenGenerator,
  onError,
}: {
  onListValueChange: (value: string) => void;
  onListInserted: (list: List) => void;
  onOpenGenerator: () => void;
  onError: () => void;
}) => {
  const { selectedList, document, hasReferenceList } = useDocsWidgetPopupContext();
  const [isLoading, setIsLoading] = useState(false);
  const { portalRef } = useContext(PortalContext);
  const { folders } = useSessionStorageContext();
  const { t } = useTranslation();
  const { settings } = useSettingsContext();

  const addToDocs = useCallback(
    async (list: List) => {
      if (document) {
        setIsLoading(true);
        if (!hasReferenceList) {
          pastePlaceholder();
          await new Promise((resolve) => setTimeout(resolve, 500));
        }

        if (settings.googleDocsToken === undefined) {
          throw new Error("Google Docs token is not set");
        }

        const response = await sendMessage({
          type: "addToDocs",
          list,
          docsId: document.documentId,
          token: settings.googleDocsToken,
        });

        setIsLoading(false);
        if (response.type === "googleDoc") {
          onListInserted(list);
        } else {
          onError();
        }
      }
    },
    [document, hasReferenceList, onError, onListInserted, settings.googleDocsToken],
  );

  const getListEntryName = (list: List) => {
    return `${list.settings.name} (${list.sourceCount} ${list.sourceCount === 1 ? "source" : "sources"})`;
  };

  const folderItems = useMemo(() => {
    return folders
      ?.sort((a, b) => Number(b.isRoot) - Number(a.isRoot))
      .map((folder) => ({
        id: folder.id,
        name: folder.isRoot ? undefined : folder.name,
        lists: folder.lists.sort((a, b) => new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime()),
      }));
  }, [folders]);

  if (!selectedList || !folderItems) {
    return (
      <div className="flex flex-col items-center justify-center space-y-3">
        <div className="text-center text-sm text-navy-blue-11">{t("docsWidget.createList.description")}</div>
        <Button
          size="sm"
          variant="solid"
          color="blue"
          as="a"
          href="https://www.scribbr.com/citation/generator/"
          onClick={onOpenGenerator}
          target="_blank"
        >
          {t("docsWidget.createList.openGenerator")}
        </Button>
      </div>
    );
  }

  return (
    <>
      <div className="mb-4 text-sm text-navy-blue-11">{t("docsWidget.selectList.description")}</div>
      <div className="flex flex-col space-y-5">
        <Select.Root value={selectedList.id} onValueChange={onListValueChange}>
          <Select.Trigger size="sm" className="col-span-2">
            {getListEntryName(selectedList)}
          </Select.Trigger>
          <Select.Content portalContainer={portalRef?.current} className="z-[751]" disableZIndex>
            {folderItems.map((folder) => (
              <Select.Group key={folder.id}>
                {folder.name && <Select.Label>{folder.name}</Select.Label>}
                {folder.lists.map((list) => (
                  <Select.Item key={list.id} value={list.id} disabled={list.sourceCount === 0}>
                    {getListEntryName(list)}
                  </Select.Item>
                ))}
              </Select.Group>
            ))}
          </Select.Content>
        </Select.Root>

        <Button
          size="sm"
          variant="solid"
          color="blue"
          onClick={() => addToDocs(selectedList)}
          loading={document === undefined || isLoading || selectedList.sourceCount === 0}
        >
          <div className="flex flex-row items-center justify-center gap-x-2">
            {hasReferenceList ? t("docsWidget.selectList.update") : t("docsWidget.selectList.insert")}
          </div>
        </Button>
      </div>
    </>
  );
};

const Login = ({ onClick }: { onClick: () => void }) => {
  const { userInfo } = useSessionStorageContext();
  const { settings } = useSettingsContext();
  const { t } = useTranslation();

  return (
    <div className="flex flex-col items-center justify-center space-y-5">
      <div className="text-navy-blue text-center text-sm">{t("docsWidget.login.description")}</div>
      <div className="w-full rounded-lg border border-navy-blue-7">
        {settings.googleDocsToken && userInfo?.level !== UserLevel.REGISTERED ? (
          <div className="flex flex-col space-y-3 p-3 text-center">
            <div className="text-navy-blue text-sm font-semibold">{t("docsWidget.login.scribbr")}</div>
            <div className="flex flex-row justify-center space-x-3">
              <Button
                size="sm"
                variant="solid"
                color="blue"
                as="a"
                href="https://app.scribbr.com/account/login/?source=extension"
                target="_blank"
                onClick={onClick}
              >
                {t("docsWidget.login.logIn")}
              </Button>
            </div>
          </div>
        ) : (
          <>
            <div className="flex flex-col space-y-3 border-b border-b-navy-blue-7 p-3 text-center">
              <div className="text-navy-blue flex flex-row items-center justify-center space-x-2 text-sm font-semibold">
                {userInfo?.level === UserLevel.REGISTERED && (
                  <CircleCheck aria-label="check" className="h-3.5 w-3.5 fill-green-9" />
                )}
                <span>
                  {userInfo?.level !== UserLevel.REGISTERED && "1. "}
                  {t("docsWidget.login.scribbr")}
                </span>
              </div>
              {userInfo?.level !== UserLevel.REGISTERED && (
                <div className="flex flex-row justify-center space-x-3">
                  <Button
                    size="sm"
                    variant="solid"
                    color="blue"
                    as="a"
                    href="https://app.scribbr.com/account/login/?source=extension"
                    target="_blank"
                    onClick={onClick}
                  >
                    {t("docsWidget.login.logIn")}
                  </Button>
                  <Button
                    size="sm"
                    variant="outline"
                    as="a"
                    href="https://app.scribbr.com/account/sign-up/?source=extension"
                    target="_blank"
                    onClick={onClick}
                  >
                    {t("docsWidget.login.signUp")}
                  </Button>
                </div>
              )}
            </div>

            <div className="flex flex-col space-y-3 border-b border-b-navy-blue-7 p-3 text-center">
              <div
                className={classNames("text-sm font-semibold", {
                  "text-navy-blue": userInfo?.level === UserLevel.REGISTERED,
                  "text-navy-blue-11": userInfo?.level !== UserLevel.REGISTERED,
                })}
              >
                2. {t("docsWidget.login.linkAccount")}
              </div>
              {userInfo?.level === UserLevel.REGISTERED && !settings.googleDocsToken && (
                <div className="flex flex-row justify-center space-x-3">
                  <Button
                    size="sm"
                    variant="solid"
                    color="blue"
                    as="a"
                    href={chrome.runtime.getURL("google-docs.html")}
                    target="_blank"
                  >
                    {t("docsWidget.login.goToSettings")}
                  </Button>
                </div>
              )}
            </div>

            <div className="flex flex-col space-y-3 p-3 text-center">
              <div className="text-sm font-semibold text-navy-blue-11">3. Add your list to your document</div>
            </div>
          </>
        )}
      </div>
    </div>
  );
};
